import React, { useEffect, useState } from 'react';
import { Card, Table, Button, Space, Form, Input, Select, message, Typography, InputNumber, Tag } from 'antd';
import HyperloopDSLValidator from '../components/HyperloopDSLValidator';

type TestItem = {
  test_key: string;
  title: string;
  category?: string;
  severity?: string;
  role_context?: string;
  schedule_minutes?: number;
};

type ResultItem = {
  id: string;
  test_key: string;
  status: string;
  metrics: any;
  detail?: string;
  created_at?: string;
};

const buildAuthHeaders = () => {
  let tgId: string | null = null;
  try { tgId = sessionStorage.getItem('tg_id'); } catch {}
  return tgId ? { 'X-Telegram-User-ID': String(tgId) } : {};
};

const GendarmePanel: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [tests, setTests] = useState<TestItem[]>([]);
  const [results, setResults] = useState<ResultItem[]>([]);
  const [filterCategory, setFilterCategory] = useState<string | undefined>('P30');
  const [registerForm] = Form.useForm();
  const [schedulerInterval, setSchedulerInterval] = useState<number>(60);
  const [expMinutes, setExpMinutes] = useState<number>(120);
  const [inspMinutes, setInspMinutes] = useState<number>(60);
  const [trendKey, setTrendKey] = useState<string>('skill_chain.apply_and_trace.demo.skill');
  const [trendLimit, setTrendLimit] = useState<number>(30);
  const [trendAgg, setTrendAgg] = useState<{avg_ms:number;p95_ms:number;pass_rate:number;count:number}|null>(null);

  const loadTests = async () => {
    try {
      setLoading(true);
      const url = filterCategory ? `/api/admin/gendarme/tests?category=${encodeURIComponent(filterCategory)}` : '/api/admin/gendarme/tests';
      const resp = await fetch(url, { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error('load tests');
      const data = await resp.json();
      setTests(data.items || []);
    } catch { message.error('Не удалось загрузить тесты'); } finally { setLoading(false); }
  };

  const loadResults = async (testKey?: string) => {
    try {
      setLoading(true);
      const url = testKey ? `/api/admin/gendarme/tests/results?limit=50&test_key=${encodeURIComponent(testKey)}` : '/api/admin/gendarme/tests/results?limit=50';
      const resp = await fetch(url, { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error('load results');
      const data = await resp.json();
      setResults(data.items || []);
    } catch { message.error('Не удалось загрузить результаты'); } finally { setLoading(false); }
  };

  const loadTrend = async () => {
    try {
      setLoading(true);
      const url = `/api/admin/gendarme/tests/results?limit=${trendLimit}&test_key=${encodeURIComponent(trendKey)}`;
      const resp = await fetch(url, { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error('load trend');
      const data = await resp.json();
      setResults(data.items || []);
      // агрегаты
      const aresp = await fetch(`/api/admin/gendarme/tests/trend-agg?test_key=${encodeURIComponent(trendKey)}&limit=${trendLimit}`, { headers: buildAuthHeaders() });
      if (aresp.ok) {
        const agg = await aresp.json();
        if (agg && agg.ok) setTrendAgg({ avg_ms: agg.avg_ms||0, p95_ms: agg.p95_ms||0, pass_rate: agg.pass_rate||0, count: agg.count||0 });
        else setTrendAgg(null);
      } else { setTrendAgg(null); }
    } catch { message.error('Не удалось загрузить тренд'); } finally { setLoading(false); }
  };

  useEffect(() => { loadTests(); loadResults(); }, [filterCategory]);

  const runTest = async (key: string) => {
    try {
      const resp = await fetch('/api/admin/gendarme/tests/run', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ test_key: key })
      });
      if (!resp.ok) throw new Error();
      const data = await resp.json();
      message.success(`Тест выполнен: ${data.status}`);
      await loadResults(key);
    } catch { message.error('Не удалось выполнить тест'); }
  };

  const registerTest = async () => {
    try {
      const v = await registerForm.validateFields();
      const resp = await fetch('/api/admin/gendarme/tests/register', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify(v)
      });
      if (!resp.ok) throw new Error();
      message.success('Тест зарегистрирован');
      registerForm.resetFields();
      await loadTests();
    } catch { message.error('Не удалось зарегистрировать тест'); }
  };

  const saveScheduler = async () => {
    try {
      await fetch('/api/admin/soul/settings', { method:'PUT', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ key:'gendarme.scheduler_interval_sec', value: schedulerInterval }) });
      await fetch('/api/admin/soul/settings', { method:'PUT', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ key:'tests.schedule.p29_experiments_smoke.minutes', value: expMinutes }) });
      await fetch('/api/admin/soul/settings', { method:'PUT', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ key:'tests.schedule.p29.experiments.window24h.minutes', value: inspMinutes }) });
      message.success('Расписание обновлено');
    } catch { message.error('Не удалось сохранить расписание'); }
  };

  return (
    <Card title="Gendarme — Тесты и Регрессия" loading={loading}>
      <Space direction="vertical" style={{ width: '100%', boxSizing: 'border-box', maxWidth: '100%' }} size={12}>
        <Space wrap>
          <Select
            placeholder="Категория"
            value={filterCategory}
            onChange={setFilterCategory}
            allowClear
            options={[
              { label: 'P30', value: 'P30' },
              { label: 'P29', value: 'P29' },
              { label: 'skill_chain', value: 'skill_chain' },
              { label: 'ALL', value: undefined as any },
            ]}
            style={{ minWidth: 160 }}
          />
          <Button onClick={() => { loadTests(); loadResults(); }}>Обновить</Button>
          <Button type="primary" onClick={async ()=>{
            try{
              const resp = await fetch('/api/admin/gendarme/tests/run-suite', {
                method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' },
                body: JSON.stringify(filterCategory ? { category: filterCategory } : {})
              });
              if(!resp.ok) throw new Error();
              const data = await resp.json();
              message.success(`Suite: passed ${data.passed}/${data.total}`);
              await loadResults();
            }catch{ message.error('Не удалось выполнить Suite'); }
          }}>Run Suite</Button>
          <Button onClick={async()=>{
            const key = prompt('Введите skill_key (например, demo.skill)');
            if(!key) return;
            try{
              const resp = await fetch('/api/admin/gendarme/tests/run', {
                method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' },
                body: JSON.stringify({ test_key: `skill_chain.apply_and_trace.${key}` })
              });
              if(!resp.ok) throw new Error();
              const data = await resp.json();
              message.success(`SKILL.TEST: ${data.status}`);
              await loadResults(`skill_chain.apply_and_trace.${key}`);
            }catch{ message.error('Не удалось выполнить SKILL.TEST'); }
          }}>SKILL.TEST (apply_and_trace)</Button>
        </Space>

        <Card size="small" title="Профили и SKILL.SUITE под профилем">
          <Space wrap>
            <Button onClick={async()=>{
              try{
                const resp = await fetch('/api/admin/gendarme/flags/apply-profile', { method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ profile:'prod_safe' }) });
                if(!resp.ok) throw new Error();
                message.success('Профиль prod_safe применён');
              }catch{ message.error('Не удалось применить prod_safe'); }
            }}>Apply prod_safe</Button>
            <Button onClick={async()=>{
              try{
                const resp = await fetch('/api/admin/gendarme/flags/apply-profile', { method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ profile:'dev_full' }) });
                if(!resp.ok) throw new Error();
                message.success('Профиль dev_full применён');
              }catch{ message.error('Не удалось применить dev_full'); }
            }}>Apply dev_full</Button>
            <Button type="primary" onClick={async()=>{
              try{
                const resp = await fetch('/api/admin/gendarme/skill/run-suite-profiled', { method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ profile:'prod_safe', category:'skill_chain' }) });
                if(!resp.ok) throw new Error();
                const data = await resp.json();
                message.success(`Suite@prod_safe: passed ${data.passed}/${data.total}`);
                await loadResults();
              }catch{ message.error('Не удалось выполнить Suite@prod_safe'); }
            }}>Run SKILL.SUITE (prod_safe)</Button>
            <Button type="default" onClick={async()=>{
              try{
                const resp = await fetch('/api/admin/gendarme/skill/run-suite-profiled', { method:'POST', headers:{ ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify({ profile:'dev_full', category:'skill_chain' }) });
                if(!resp.ok) throw new Error();
                const data = await resp.json();
                message.success(`Suite@dev_full: passed ${data.passed}/${data.total}`);
                await loadResults();
              }catch{ message.error('Не удалось выполнить Suite@dev_full'); }
            }}>Run SKILL.SUITE (dev_full)</Button>
          </Space>
        </Card>

        <Card size="small" title="Тренд по test_key (duration_ms)">
          <Space align="center" wrap>
            <Input placeholder="test_key" value={trendKey} onChange={(e:any)=>setTrendKey(e.target.value)} style={{ width: 360 }} />
            <InputNumber min={5} max={200} value={trendLimit} onChange={(v:any)=>setTrendLimit(Number(v||30))} />
            <Button onClick={loadTrend}>Загрузить тренд</Button>
            {trendAgg && (
              <Space>
                <Tag color="blue">avg {trendAgg.avg_ms} ms</Tag>
                <Tag color="purple">p95 {trendAgg.p95_ms} ms</Tag>
                <Tag color="green">pass {Math.round(trendAgg.pass_rate*100)}%</Tag>
                <Tag>n={trendAgg.count}</Tag>
              </Space>
            )}
          </Space>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: 6, height: 160, marginTop: 12, border: '1px dashed var(--sp-border-color, #eee)', padding: 8, boxSizing: 'border-box', maxWidth: '100%', overflowX: 'hidden' }}>
            {results.map((r, idx)=>{
              const v = Math.max(0, Number((r.metrics||{}).duration_ms||0));
              const max = Math.max(1, ...results.map(x=>Number((x.metrics||{}).duration_ms||0)));
              const h = Math.max(4, Math.round(140 * v / max));
              const color = r.status === 'passed' ? '#52c41a' : '#ff4d4f';
              return <div key={r.id||idx} title={`${r.created_at||''} ${v}ms`} style={{ width:10, height:h, background:color }} />;
            })}
          </div>
        </Card>

        <Card size="small" title="Зарегистрированные тесты">
          <Table
            rowKey={(r) => r.test_key}
            size="small"
            pagination={{ pageSize: 8 }}
            dataSource={tests}
            columns={[
              { title: 'test_key', dataIndex: 'test_key', width: 220 },
              { title: 'title', dataIndex: 'title' },
              { title: 'category', dataIndex: 'category', width: 100 },
              { title: 'severity', dataIndex: 'severity', width: 100 },
              { title: 'schedule (min)', dataIndex: 'schedule_minutes', width: 130 },
              { title: 'Действия', width: 140, render: (_: any, row: TestItem) => (
                <Space>
                  <Button size="small" onClick={() => runTest(row.test_key)}>Run</Button>
                  <Button size="small" onClick={() => loadResults(row.test_key)}>Results</Button>
                </Space>
              ) },
            ]}
          />
        </Card>

        <Card size="small" title="Регистрация теста">
          <Form form={registerForm} layout="inline">
            <Form.Item name="test_key" rules={[{ required: true }]}>
              <Input placeholder="test_key" style={{ width: 220 }} />
            </Form.Item>
            <Form.Item name="title" rules={[{ required: true }]}>
              <Input placeholder="title" style={{ width: 220 }} />
            </Form.Item>
            <Form.Item name="category" initialValue="P29">
              <Input placeholder="category" style={{ width: 120 }} />
            </Form.Item>
            <Form.Item name="severity" initialValue="medium">
              <Input placeholder="severity" style={{ width: 120 }} />
            </Form.Item>
            <Form.Item name="schedule_minutes">
              <Input placeholder="schedule (min)" style={{ width: 140 }} />
            </Form.Item>
            <Button type="primary" onClick={registerTest}>Register</Button>
          </Form>
        </Card>

        <Card size="small" title="Последние результаты">
          <Table
            rowKey={(r) => r.id}
            size="small"
            pagination={{ pageSize: 8 }}
            dataSource={results}
            columns={[
              { title: 'created_at', dataIndex: 'created_at', width: 180 },
              { title: 'test_key', dataIndex: 'test_key', width: 220 },
              { title: 'status', dataIndex: 'status', width: 100, render: (v: string) => (
                <Typography.Text type={v === 'passed' ? 'success' : 'danger'}>{v}</Typography.Text>
              ) },
              { title: 'metrics', dataIndex: 'metrics', render: (v: any) => <code style={{fontSize:12}}>{JSON.stringify(v)}</code> },
              { title: 'detail', dataIndex: 'detail', render: (v: any) => <div style={{whiteSpace:'pre-wrap'}}>{String(v||'')}</div> },
            ]}
          />
        </Card>

        <HyperloopDSLValidator title="Hyperloop DSL — валидатор/нормализация (общий)" />
      </Space>
    </Card>
  );
};

export default GendarmePanel;


